using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using Object=UnityEngine.Object;
public static class RebirthCamperDoorSlopeAudit{
 const string O="E:/_Haven/shared/REBIRTHTemp/CamperDoorSlope_20261015";
 public static void Run(){Directory.CreateDirectory(O);EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);var p=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/REBIRTHCamperFrontProfile_20261015_v7/rebirthCamper80s.prefab");var report=new List<string>();foreach(string variant in new[]{"baseline","clearance104"})foreach(float pitch in new[]{-10f,0f,10f})foreach(float roll in new[]{-10f,0f,10f})foreach(float x in new[]{0f,-.08f,.08f}){var root=Object.Instantiate(p);root.transform.rotation=Quaternion.Euler(pitch,0,roll);RebirthCamperCampIntegration.SetMode(root,true);foreach(var c in root.GetComponentsInChildren<Collider>(true)){if(c.name=="Camp rear jamb"&&(variant=="no-jamb"||variant.StartsWith("wider-jamb"))){var box=(BoxCollider)c;if(variant=="no-jamb")c.enabled=false;else{box.center+=new Vector3(Mathf.Sign(box.center.x)*.06f,0,0);box.size-=new Vector3(.12f,0,0);}}if(c.name=="REBIRTHRearDoorPivot"&&(variant=="no-door"||variant=="wider-jamb-no-door"))c.enabled=false;}if(variant=="clearance104"){foreach(var b in root.GetComponentsInChildren<BoxCollider>(true).Where(b=>b.name=="Camp rear jamb")){b.center=new Vector3(Mathf.Sign(b.center.x)*.71f,b.center.y,b.center.z);b.size=new Vector3(.38f,b.size.y,b.size.z);}var door=root.GetComponentsInChildren<Transform>(true).Single(t=>t.name=="REBIRTHRearDoorPivot");door.localPosition+=new Vector3(.12f,0,0);door.localRotation=Quaternion.Euler(0,-130,0);var d=door.GetComponent<BoxCollider>();d.center=new Vector3(-.52f,d.center.y,d.center.z);d.size=new Vector3(1.04f,d.size.y,d.size.z);}Physics.SyncTransforms();if(roll==0&&x==0)foreach(var c in root.GetComponentsInChildren<Collider>(true).Where(c=>c.enabled&&!c.isTrigger&&c.gameObject.activeInHierarchy)){var b=c as BoxCollider;report.Add("COLLIDER "+c.name+" localPos="+c.transform.localPosition.ToString("F4")+" localRot="+c.transform.localEulerAngles.ToString("F2")+" box="+(b?b.center.ToString("F4")+" size="+b.size.ToString("F4"):c.GetType().Name)+" worldBounds="+c.bounds);}
 var start=root.transform.TransformPoint(new Vector3(x,.03f,-5.5f));var ground=GameObject.CreatePrimitive(PrimitiveType.Cube);ground.transform.position=new Vector3(0,start.y-.18f,-4);ground.transform.localScale=new Vector3(15,.3f,15);var go=new GameObject("PlayerAudit");var cc=go.AddComponent<CharacterController>();cc.height=1.8f;cc.radius=.35f;cc.center=Vector3.up*.9f;cc.skinWidth=.08f;cc.stepOffset=.1f;cc.slopeLimit=50;cc.minMoveDistance=0;var contacts=go.AddComponent<CamperAuditContacts>();go.transform.position=start;Physics.SyncTransforms();for(int i=0;i<650&&root.transform.InverseTransformPoint(go.transform.position).z< -1.6f;i++)cc.Move(new Vector3(0,-.03f,.012f));var local=root.transform.InverseTransformPoint(go.transform.position);report.Add("WALK variant="+variant+" pitch="+pitch+" roll="+roll+" offset="+x+" localEnd="+local.ToString("F4")+" PASS="+(local.z> -2)+" contacts="+string.Join(";",contacts.Contacts));Object.DestroyImmediate(go);Object.DestroyImmediate(ground);Object.DestroyImmediate(root);}File.WriteAllLines(O+"/candidate104-pitch.txt",report);}
